        node2_name = (await GriptapeNodes.ahandle_request(CreateNodeRequest(node_type='GenerateImage', specific_library_name='Griptape Nodes Library', node_name='Generate Image - Your Frame', metadata={'position': {'x': 200, 'y': 2874}, 'library_node_metadata': {'category': 'image', 'description': 'Generates an image using Griptape Cloud, or other provided image generation models', 'display_name': 'Generate Image', 'tags': ['image', 'generation', 'ai'], 'icon': None, 'color': None, 'group': 'create', 'deprecation': None, 'is_node_group': None, 'declarations': [{'type': 'model_usage', 'model_ids': ['gtc_gpt_image_1_mini', 'gtc_gpt_image_1_5', 'gtc_gpt_4o']}]}, 'library': 'Griptape Nodes Library', 'node_type': 'GenerateImage', 'size': {'width': 1200, 'height': 1670}}, initial_setup=True))).node_name
